#!/bin/bash
# T014: Orchestrate baseline training on Lorenz (train) and Polynomials (test)
# Explicitly invokes /usr/bin/time -v to verify FR-004 constraints:
# - Wall-clock time limit: 6 hours (21600 seconds)
# - RAM threshold: < 7 GB RSS
#
# Output: data/results/baseline_metrics.json (generated by Python script)
# Output: data/logs/time_resources.log (generated by /usr/bin/time -v)

set -euo pipefail

# Configuration
PROJECT_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
SCRIPT_DIR="${PROJECT_ROOT}/code/scripts"
DATA_DIR="${PROJECT_ROOT}/data"
LOG_DIR="${DATA_DIR}/logs"
RESULTS_DIR="${DATA_DIR}/results"

# Ensure directories exist
mkdir -p "${LOG_DIR}" "${RESULTS_DIR}"

# Resource constraints (FR-004)
TIME_LIMIT_SECONDS=21600  # 6 hours
RAM_LIMIT_GB=7

echo "========================================"
echo "Baseline Training Pipeline (T014)"
echo "========================================"
echo "Project Root: ${PROJECT_ROOT}"
echo "Time Limit: ${TIME_LIMIT_SECONDS} seconds"
echo "RAM Limit: ${RAM_LIMIT_GB} GB"
echo "========================================"

# Change to project root for relative imports
cd "${PROJECT_ROOT}"

# Define output paths
TIME_OUTPUT="${LOG_DIR}/time_resources.log"
PYTHON_SCRIPT="${SCRIPT_DIR}/run_baseline_training.py"

# Check if Python script exists
if [[ ! -f "${PYTHON_SCRIPT}" ]]; then
    echo "ERROR: Python training script not found at ${PYTHON_SCRIPT}"
    echo "This script must be created by T015 (src/experiments/baseline_runner.py) or similar."
    exit 1
fi

# Run training with /usr/bin/time -v
echo "Starting baseline training with resource monitoring..."
echo "Output will be logged to: ${TIME_OUTPUT}"

# Use /usr/bin/time -v to capture detailed resource usage
# Redirect stderr (where -v output goes) to our log file
/usr/bin/time -v -o "${TIME_OUTPUT}" -f "Elapsed: %E\nMaxRSS: %M KB\nExit: %x" \
    python -u "${PYTHON_SCRIPT}" \
    --train-task "lorenz" \
    --test-task "polynomial" \
    --epochs 10 \
    --batch-size 32 \
    --lr 0.001 \
    --seed 42 \
    --output "${RESULTS_DIR}/baseline_metrics.json" \
    2>&1 | tee "${LOG_DIR}/training_stdout.log"

# Capture exit code
TRAIN_EXIT_CODE=${PIPESTATUS[0]}

echo "========================================"
echo "Training Completed (Exit Code: ${TRAIN_EXIT_CODE})"
echo "========================================"

# Verify training succeeded
if [[ ${TRAIN_EXIT_CODE} -ne 0 ]]; then
    echo "ERROR: Training script failed with exit code ${TRAIN_EXIT_CODE}"
    echo "Check logs at: ${LOG_DIR}/training_stdout.log"
    exit ${TRAIN_EXIT_CODE}
fi

# Parse /usr/bin/time -v output for resource verification
echo "Verifying resource constraints..."

# Extract MaxRSS (in KB) from time output
MAXRSS_KB=$(grep "Maximum resident set size (kbytes):" "${TIME_OUTPUT}" | awk '{print $NF}')

if [[ -z "${MAXRSS_KB}" ]]; then
    echo "WARNING: Could not extract MaxRSS from time output. Resource verification skipped."
else
    # Convert KB to GB
    MAXRSS_GB=$(echo "scale=2; ${MAXRSS_KB} / 1024 / 1024" | bc)
    echo "Max RSS: ${MAXRSS_GB} GB (Limit: ${RAM_LIMIT_GB} GB)"

    # Check RAM constraint
    if (( $(echo "${MAXRSS_GB} > ${RAM_LIMIT_GB}" | bc -l) )); then
        echo "ERROR: RAM constraint violated! Used ${MAXRSS_GB} GB > ${RAM_LIMIT_GB} GB limit"
        exit 1
    else
        echo "✓ RAM constraint satisfied"
    fi
fi

# Extract elapsed time (format: H:MM:SS or M:SS)
ELAPSED=$(grep "Elapsed (wall clock)" "${TIME_OUTPUT}" | awk '{print $NF}')
echo "Elapsed time: ${ELAPSED}"

# Convert elapsed time to seconds for comparison
# Handle both H:MM:SS and M:SS formats
if [[ ${ELAPSED} == *:*:* ]]; then
    # H:MM:SS format
    HOURS=$(echo ${ELAPSED} | cut -d: -f1)
    MINS=$(echo ${ELAPSED} | cut -d: -f2)
    SECS=$(echo ${ELAPSED} | cut -d: -f3)
    TOTAL_SECS=$((10#$HOURS * 3600 + 10#$MINS * 60 + 10#$SECS))
else
    # M:SS format
    MINS=$(echo ${ELAPSED} | cut -d: -f1)
    SECS=$(echo ${ELAPSED} | cut -d: -f2)
    TOTAL_SECS=$((10#$MINS * 60 + 10#$SECS))
fi

echo "Elapsed time (seconds): ${TOTAL_SECS}"

# Check time constraint
if [[ ${TOTAL_SECS} -gt ${TIME_LIMIT_SECONDS} ]]; then
    echo "ERROR: Time constraint violated! Used ${TOTAL_SECS}s > ${TIME_LIMIT_SECONDS}s limit"
    exit 1
else
    echo "✓ Time constraint satisfied"
fi

# Verify output file exists
if [[ ! -f "${RESULTS_DIR}/baseline_metrics.json" ]]; then
    echo "ERROR: Expected output file not found: ${RESULTS_DIR}/baseline_metrics.json"
    exit 1
fi

echo "========================================"
echo "Baseline Training Pipeline: SUCCESS"
echo "========================================"
echo "Metrics saved to: ${RESULTS_DIR}/baseline_metrics.json"
echo "Resource log saved to: ${TIME_OUTPUT}"
cat "${RESULTS_DIR}/baseline_metrics.json"
echo "========================================"

exit 0
